def solve(expr):
    def apply_op(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def evaluate(expression):
        stack = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                start = i
                while i < len(expression) and expression[i].isdigit():
                    i += 1
                stack.append(int(expression[start:i]))
                i -= 1
            elif expression[i] in '+-*/':
                stack.append(expression[i])
            i += 1

        stack2 = []
        i = 0
        while i < len(stack):
            if isinstance(stack[i], int):
                stack2.append(stack[i])
            else:
                b = stack2.pop()
                a = stack2.pop()
                stack2.append(apply_op(stack[i], a, b))
            i += 1

        return stack2[0]

    return evaluate(expr.replace(' ', ''))

# Example usage:
print(solve("3+2*2"))  # Output: 7
print(solve(" 3/2 "))  # Output: 1
print(solve(" 3+5 / 2 "))  # Output: 5
